    Catalog c;auto resources=NativeResources::inspect(source,patches,cancel);if(resources["format"]!="PGR2 indexed resources")return c;QMap<QString,QJsonObject> rows;for(auto value:resources["entries"].toArray()){auto r=value.toObject();rows[r["name"].toString()]=r;}if(!rows.contains("WMSH"))return c;auto fail=[&](QString e){c.error=e;c.draws.clear();return c;};for(auto name:{"MAT","TEX","VB","GPUD"})if(!rows.contains(name))return fail(QString("PGR2 WMSH is missing %1.").arg(name));auto get=[&](QString name){auto result=NativeResources::extract(source,patches,rows[name],cancel);if(!result.error.isEmpty())c.error=result.error;return result.bytes;};c.tree=get("WMSH");c.gpu=get("GPUD");auto mats=get("MAT"),tex=get("TEX"),vb=get("VB");if(!c.error.isEmpty())return fail(c.error);if(mats.size()<4||tex.size()<4||vb.isEmpty()||vb.size()%4||c.tree.size()<48)return fail("Incomplete PGR2 track tables.");auto numMats=qFromLittleEndian<quint32>(mats.constData()),numTex=qFromLittleEndian<quint32>(tex.constData());if(numMats>100000||numTex>10000||4+qint64(numMats)*8>mats.size()||4+qint64(numTex)*48>tex.size())return fail("PGR2 track material/texture ranges are invalid.");
    for(quint32 i=0;i<numMats;++i){auto p=mats.constData()+4+i*8;Material m;m.texture=std::bit_cast<qint16>(qFromLittleEndian<quint16>(p));m.flags=qFromLittleEndian<quint16>(p+4);m.shader=quint8(p[6]);m.declaration=quint8(p[7]);if(m.texture>=int(numTex))return fail("PGR2 track material references an unknown texture.");c.materials.append(m);}
